import math
import numpy as np

def strategy(hist, state, pos, ind):
    current = len(hist) - 1
    # Constants for parameter values
    fast_n = 5
    slow_n = 50
    atr_period = 14
    stop_k = 1.5
    time_stop_n = 16
    sizing_fraction = 1.0
    htf_minutes = 240
    htf_ema_n = 20

    # Get current close and ATR
    close = hist.close
    high = hist.high
    low = hist.low

    # Compute indicators
    fast_ema = ind.ema(close, fast_n)
    slow_ema = ind.ema(close, slow_n)
    atr = ind.atr(hist, atr_period)

    # Higher timeframe filter
    htf = hist.htf(htf_minutes)
    htf_close = htf.close
    htf_ema = ind.ema(htf_close, htf_ema_n)

    if len(hist) < fast_n or len(hist) < slow_n:
        return {"target": 0.0, "stop": None, "take": None}

    current_signal_cross = None
    # Determine signal: EMA crossover
    if current >= 1:
        prev_fast = fast_ema[-2] if not np.isnan(fast_ema[-2]) else None
        prev_slow = slow_ema[-2] if not np.isnan(slow_ema[-2]) else None
        curr_fast = fast_ema[-1] if not np.isnan(fast_ema[-1]) else None
        curr_slow = slow_ema[-1] if not np.isnan(slow_ema[-1]) else None
        if prev_fast is not None and prev_slow is not None and curr_fast is not None and curr_slow is not None:
            if prev_fast <= prev_slow and curr_fast > curr_slow:
                current_signal_cross = 'long'
            elif prev_fast >= prev_slow and curr_fast < curr_slow:
                current_signal_cross = 'short'

    # Check opposite signal to exit
    if pos != 0.0:
        # If we are long and get a short signal -> exit
        if pos > 0 and current_signal_cross == 'short':
            return {"target": 0.0, "stop": None, "take": None}
        # If we are short and get a long signal -> exit
        if pos < 0 and current_signal_cross == 'long':
            return {"target": 0.0, "stop": None, "take": None}

    # Time stop: check if trade has been open for enough bars
    if pos != 0.0:
        signal_bar = state.get('signal_bar', None)
        if signal_bar is not None and current - signal_bar >= time_stop_n:
            return {"target": 0.0, "stop": None, "take": None}

    # If we have a position, manage stops and return existing target
    if pos != 0.0:
        entry_price = state.get('entry_price', None)
        entry_atr = state.get('entry_atr', None)
        if entry_price is None or entry_atr is None:
            return {"target": 0.0, "stop": None, "take": None}

        # Calculate hard stop
        if pos > 0:
            stop_price = entry_price - stop_k * entry_atr
            take_price = None
        else:
            stop_price = entry_price + stop_k * entry_atr
            take_price = None

        # Keep current position (no change)
        target = pos
        return {"target": target, "stop": stop_price, "take": take_price}

    # No position: check for new entry
    if current_signal_cross is None:
        return {"target": 0.0, "stop": None, "take": None}

    # Check HTF filter
    last_htf_close = htf_close[-1] if not np.isnan(htf_close[-1]) else None
    last_htf_ema = htf_ema[-1] if not np.isnan(htf_ema[-1]) else None
    if last_htf_close is None or last_htf_ema is None:
        return {"target": 0.0, "stop": None, "take": None}

    if current_signal_cross == 'long' and not (last_htf_close > last_htf_ema):
        return {"target": 0.0, "stop": None, "take": None}
    if current_signal_cross == 'short' and not (last_htf_close < last_htf_ema):
        return {"target": 0.0, "stop": None, "take": None}

    # Determine target based on sizing: fixed fraction of equity
    # sizing_fraction = 1.0 means full equity long or short
    if current_signal_cross == 'long':
        target = sizing_fraction
    else:
        target = -sizing_fraction

    # Round to 0.05 grid
    target = round(target / 0.05) * 0.05
    target = max(-1.0, min(1.0, target))

    # Save signal bar and entry info for potential position management
    # We record the current bar as signal bar
    state['signal_bar'] = float(current)
    state['entry_price'] = float(close[-1])  # signal bar close
    state['entry_atr'] = float(atr[-1]) if not np.isnan(atr[-1]) else float(atr[-2] if len(atr) > 1 else 0.0)

    # For a new entry, we set stop but no take (hard stop only)
    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    if target > 0:
        stop_price = entry_price - stop_k * entry_atr
    else:
        stop_price = entry_price + stop_k * entry_atr

    return {"target": target, "stop": stop_price, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind):
    # Current bar's close
    close = hist.close[-1]

    # Donchian levels: highest high and lowest low of the prior 48 bars
    hh48 = ind.highest(hist.high, 48)[-2]
    ll48 = ind.lowest(hist.low, 48)[-2]

    # Current ATR(14)
    atr = ind.atr(hist, 14)[-1]

    # 1-hour trend filter: last completed 1h close > its 20-period EMA
    htf_close = hist.htf(60).close
    ema_1h = ind.ema(htf_close, 20)
    filter_ok = htf_close[-1] > ema_1h[-1]

    # If we are in a long trade
    if pos > 0:
        entry_price = state.get('entry_price', close)
        entry_atr = state.get('entry_atr', atr)
        take_price = entry_price + 2.0 * entry_atr

        # Bearish breakdown: close below the 48-bar lowest low -> exit at next open
        if close < ll48:
            return {"target": 0.0, "stop": None, "take": None}
        else:
            return {"target": pos, "stop": None, "take": take_price}

    # Flat: look for a long entry
    else:
        # Clear any stale state (optional, but harmless)
        # Entry signal: close above 48-bar highest high AND trend filter OK
        if close > hh48 and filter_ok:
            state['entry_price'] = close
            state['entry_atr'] = atr
            take_price = close + 2.0 * atr
            return {"target": 0.5, "stop": None, "take": take_price}
        else:
            return {"target": 0.0, "stop": None, "take": None}
